insert into public.dx_conditions (id, icd10, name, category, description, urgency, prior, sex, age_min, age_max, recommended_tests, advice, pubmed_query, aliases) values
('malaria','B54','Malaria (uncomplicated)','Infectious','Plasmodium infection without signs of severity. Confirm with a test before treating.','routine',0.20,'any',null,null,'{Malaria RDT,Malaria microscopy (thick and thin film),Full blood count}','Treat only test-positive cases with an ACT per national guidelines; check for danger signs.','malaria[MeSH] AND (diagnosis OR treatment) AND (Nigeria OR Africa)','{malaria,plasmodium,uncomplicated malaria}'),
('severe_malaria','B50.0','Severe malaria','Infectious','Malaria with danger signs such as impaired consciousness, convulsions, severe anaemia, jaundice or respiratory distress.','emergency',0.01,'any',null,null,'{Malaria microscopy,Full blood count,Blood glucose,Urea and electrolytes,Serum bilirubin}','Start parenteral artesunate immediately and refer or admit.','severe malaria artesunate management','{severe malaria,complicated malaria,cerebral malaria}'),
('typhoid','A01.0','Typhoid fever','Infectious','Salmonella Typhi infection. The Widal test is unreliable; blood culture is the reference test.','urgent',0.03,'any',null,null,'{Blood culture,Stool culture,Full blood count}','Avoid diagnosing on Widal alone; treat per local resistance patterns.','typhoid fever[MeSH] AND (diagnosis OR treatment) AND Africa','{typhoid,enteric fever,salmonella typhi}'),
('urti','J06.9','Upper respiratory tract infection (common cold)','Infectious','Usually viral infection of the nose and throat.','routine',0.14,'any',null,null,'{Clinical diagnosis - no routine tests}','Symptomatic care; antibiotics are not needed for viral URTI.','common cold[MeSH] management','{urti,common cold,coryza,upper respiratory tract infection}'),
('pharyngitis','J02.9','Acute tonsillopharyngitis','Infectious','Throat infection; bacterial (streptococcal) when exudate, fever, tender nodes and no cough.','routine',0.04,'any',null,null,'{Rapid strep test or throat swab culture}','Use Centor criteria to decide on antibiotics.','pharyngitis[MeSH] streptococcal diagnosis','{pharyngitis,tonsillitis,sore throat infection}'),
('ili','J11.1','Influenza-like illness / COVID-19','Infectious','Acute viral respiratory illness with fever and cough.','routine',0.04,'any',null,null,'{COVID-19 or influenza rapid test,SpO2 monitoring}','Monitor oxygen saturation; isolate while infectious.','influenza-like illness OR COVID-19 outpatient management','{influenza,flu,covid,covid-19,influenza like illness}'),
('pneumonia','J18.9','Community-acquired pneumonia','Infectious','Lung infection with fever, cough and fast breathing or low oxygen.','urgent',0.025,'any',null,null,'{Chest X-ray,Full blood count,SpO2,Sputum culture if severe}','Assess severity (CURB-65 in adults); refer if hypoxic.','community-acquired pneumonia[MeSH] management','{pneumonia,chest infection,bronchopneumonia,lobar pneumonia}'),
('tb','A15.0','Pulmonary tuberculosis','Infectious','Mycobacterium tuberculosis infection of the lungs.','urgent',0.006,'any',null,null,'{GeneXpert MTB/RIF on sputum,Chest X-ray,HIV test}','Test anyone with a cough of 2 weeks or more; notify the TB programme.','pulmonary tuberculosis diagnosis GeneXpert Nigeria','{tuberculosis,tb,ptb,pulmonary tb,koch}'),
('gastroenteritis','A09','Acute gastroenteritis','Infectious','Infective diarrhoea and/or vomiting.','routine',0.06,'any',null,null,'{Stool microscopy if prolonged or bloody,Electrolytes if dehydrated}','Oral rehydration (ORS) and zinc for children; watch for dehydration.','acute gastroenteritis[MeSH] oral rehydration','{gastroenteritis,ge,diarrhoeal disease,diarrheal disease,stomach flu}'),
('cholera','A00.9','Cholera','Infectious','Vibrio cholerae infection causing profuse watery diarrhoea and rapid dehydration.','emergency',0.002,'any',null,null,'{Cholera rapid diagnostic test,Stool culture,Electrolytes}','Rehydrate aggressively; notify NCDC/state surveillance.','cholera[MeSH] management rehydration','{cholera,vibrio cholerae}'),
('dysentery','A03.9','Dysentery (bloody diarrhoea)','Infectious','Bloody diarrhoea, usually Shigella or amoebic.','urgent',0.008,'any',null,null,'{Stool microscopy and culture}','Treat per local guidance; assess dehydration.','dysentery[MeSH] shigellosis treatment','{dysentery,shigellosis,amoebiasis,bloody diarrhoea}'),
('uti','N39.0','Urinary tract infection (lower)','Infectious','Bladder infection (cystitis).','routine',0.05,'any',null,null,'{Urinalysis (dipstick),Urine microscopy and culture}','Confirm with urinalysis; treat per local resistance.','urinary tract infection[MeSH] cystitis diagnosis','{uti,urinary tract infection,cystitis}'),
('pyelonephritis','N10','Acute pyelonephritis','Infectious','Kidney infection with fever and flank pain.','urgent',0.008,'any',null,null,'{Urinalysis,Urine culture,Full blood count,Renal function}','Consider admission if vomiting, septic or pregnant.','pyelonephritis[MeSH] management','{pyelonephritis,kidney infection}'),
('kidney_stone','N20.0','Kidney stone (renal colic)','Renal','Colicky flank pain from a stone in the urinary tract.','urgent',0.008,'any',null,null,'{Urinalysis,Abdominal ultrasound or CT KUB,Renal function}','Analgesia; refer if fever, single kidney or obstruction.','nephrolithiasis renal colic management','{kidney stone,renal colic,nephrolithiasis,urolithiasis,ureteric colic}'),
('hypertension','I10','Hypertension (uncontrolled)','Cardiovascular','Persistently raised blood pressure.','routine',0.08,'any',18,null,'{Repeat BP measurements,Urinalysis for protein,Renal function,Lipid profile,ECG}','Confirm with repeated readings; assess cardiovascular risk.','hypertension[MeSH] management sub-Saharan Africa','{hypertension,high blood pressure,htn}'),
('hypertensive_emergency','I16.1','Hypertensive emergency','Cardiovascular','Severely raised blood pressure with signs of organ damage.','emergency',0.004,'any',18,null,'{Repeat BP urgently,ECG,Renal function,Urinalysis,Fundoscopy}','Controlled BP reduction in a monitored setting; refer.','hypertensive emergency management','{hypertensive emergency,hypertensive crisis,malignant hypertension,hypertensive urgency}'),
('diabetes','E11.9','Type 2 diabetes / hyperglycaemia','Endocrine','Raised blood glucose.','routine',0.04,'any',10,null,'{Random or fasting blood glucose,HbA1c,Urinalysis}','Confirm with a second test; screen for complications.','type 2 diabetes mellitus[MeSH] diagnosis Africa','{diabetes,diabetes mellitus,dm,t2dm,type 2 diabetes,hyperglycaemia,hyperglycemia}'),
('diabetic_emergency','E11.0','Diabetic emergency (DKA/HHS)','Endocrine','Severe hyperglycaemia with ketoacidosis or hyperosmolar state.','emergency',0.002,'any',null,null,'{Blood glucose,Urine or blood ketones,Electrolytes,Blood gas if available}','Fluids, insulin and electrolyte monitoring in hospital.','diabetic ketoacidosis[MeSH] management','{dka,diabetic ketoacidosis,hhs,hyperosmolar}'),
('asthma','J45.901','Asthma attack','Respiratory','Acute bronchospasm with wheeze and breathlessness.','urgent',0.015,'any',null,null,'{Peak flow,SpO2,Chest X-ray if not improving}','Inhaled bronchodilator; assess severity; steroids if moderate or severe.','asthma exacerbation[MeSH] emergency management','{asthma,asthma attack,bronchial asthma,status asthmaticus}'),
('heart_failure','I50.9','Heart failure','Cardiovascular','The heart cannot pump enough blood, causing breathlessness and fluid build-up.','urgent',0.006,'any',18,null,'{Chest X-ray,ECG,Echocardiogram,Renal function,BNP if available}','Diuretics for congestion; find the cause (often hypertension).','heart failure[MeSH] management Africa','{heart failure,cardiac failure,ccf,chf,congestive cardiac failure}'),
('acs','I21.9','Acute coronary syndrome','Cardiovascular','Heart attack or unstable angina.','emergency',0.002,'any',25,null,'{12-lead ECG immediately,Troponin,Aspirin unless contraindicated}','Treat as an emergency; ECG within 10 minutes.','acute coronary syndrome[MeSH] diagnosis','{acute coronary syndrome,myocardial infarction,heart attack,acs,mi,unstable angina}'),
('stroke','I64','Stroke','Neurological','Sudden loss of brain function from a blocked or bleeding blood vessel.','emergency',0.002,'any',18,null,'{Urgent CT head,Blood glucose,ECG,Blood pressure monitoring}','Note the time of onset and refer immediately.','stroke[MeSH] acute management sub-Saharan Africa','{stroke,cva,cerebrovascular accident}'),
('meningitis','G03.9','Meningitis','Infectious','Infection of the brain lining; can kill within hours.','emergency',0.002,'any',null,null,'{Lumbar puncture if no contraindication,Blood culture,Full blood count}','Give antibiotics without delay; notify surveillance.','bacterial meningitis[MeSH] management Africa','{meningitis,cerebrospinal meningitis,csm}'),
('lassa','A96.2','Lassa fever','Infectious','Viral haemorrhagic fever spread by rodents and through contact with patients.','emergency',0.0008,'any',null,null,'{Isolate the patient,Lassa RT-PCR via reference laboratory (NCDC),Full blood count,Liver enzymes}','Isolate, use infection prevention precautions, and call the state epidemiologist.','Lassa fever diagnosis treatment Nigeria','{lassa,lassa fever}'),
('hepatitis','B19.9','Acute viral hepatitis','Infectious','Liver inflammation from hepatitis A, B, C or E.','urgent',0.006,'any',null,null,'{Liver function tests,HBsAg,Anti-HCV,Hepatitis A IgM}','Check for liver failure (confusion, bleeding).','acute viral hepatitis diagnosis Africa','{hepatitis,viral hepatitis,hepatitis b,hepatitis a,hepatitis c}'),
('hiv','B24','HIV infection (test indicated)','Infectious','Features that should prompt HIV testing.','urgent',0.01,'any',null,null,'{HIV rapid test with counselling,CD4 count and viral load if positive}','Offer testing with consent; link to treatment if positive.','HIV diagnosis testing Nigeria','{hiv,aids,retroviral disease}'),
